"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["91315"],{41018(e){e.exports=JSON.parse('{"id":"F100","slug":"credit-utilization","name":"Credit Utilization Ratio","subject":"Personal Finance","section":"Personal Finance","topic":"Credit scores and credit reports","level":"Beginner","aliases":["credit scores","credit score factors","revolving utilization","credit limit usage"],"formula":{"latex":"\\\\text{Utilization}=\\\\frac{\\\\sum \\\\text{Balances}}{\\\\sum \\\\text{Credit limits}}","also":[],"text":"Credit utilization = total revolving balances / total credit limits. A common guideline is to keep it under 30%, and lower is better"},"symbols":[{"symbol":"Balances","meaning":"Amounts currently owed on each credit card or revolving line","unit":"money"},{"symbol":"Credit limits","meaning":"The maximum you may borrow on each","unit":"money"}],"when_to_use":"Use it to see one of the factors that scoring models weigh heavily. Scores also reward paying on time and a long history, and penalize many new applications, so utilization is only part of the picture. Scoring details vary by country and provider, so treat 30% as a guideline, not a rule.","worked_example":{"problem":"You have three cards with balances of 1,800, 600 and 0 and limits of 5,000, 3,000 and 2,000. You want to stay under 30%.","inputs":{"bal":[1800,600,0],"lim":[5000,3000,2000],"thr":30},"steps":[{"label":"Total balances","working":null,"value":"2,400.00"},{"label":"Total limits","working":null,"value":"10,000.00"},{"label":"Overall utilization = balances / limits","working":"2400 / 10000","value":"24.0%"},{"label":"Utilization by card","working":null,"value":"36.00%, 20.00%, 0.00%"},{"label":"Total limit needed for the target at current balances","working":"2400 / 0.3","value":"8,000.00"},{"label":"Balance to pay down to reach the target now","working":"max(2400-0.3 x 10000, 0)","value":"0.00"}],"answer":"Overall utilization is 24.0%. The share used on each card is 36.00%, 20.00%, 0.00%. The limit needed to put current balances at 30% is 8,000.00, and you would have to pay off 0.00 to reach it now."},"calculator":{"available":true,"inputs":[{"id":"bal","label":"Balance on each card","unit":"money","type":"list","default":[1800,600,0],"hint":""},{"id":"lim","label":"Limit on each card","unit":"money","type":"list","default":[5000,3000,2000],"hint":""},{"id":"thr","label":"Target utilization","unit":"%","type":"number","default":30,"hint":""}],"checks":[{"expr":"count(bal)==count(lim) and sum(lim)>0 and thr>0","message":"Enter a balance and a limit for every card, and a target above zero."}],"steps":[{"id":"tb","label":"Total balances","expr":"sum(bal)","format":"money"},{"id":"tl","label":"Total limits","expr":"sum(lim)","format":"money"},{"id":"u","label":"Overall utilization = balances / limits","expr":"tb/tl","format":"pct1"},{"id":"each","label":"Utilization by card","expr":"divide(bal, lim)","format":"list2pct"},{"id":"need","label":"Total limit needed for the target at current balances","expr":"tb/thr","format":"money"},{"id":"pay","label":"Balance to pay down to reach the target now","expr":"max(tb-thr*tl, 0)","format":"money"}],"results":["u","need","pay"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"tb":2400,"tl":10000,"u":0.24,"need":8000,"pay":0}},"finder":{"finds":"How much of your available credit you are using","needs":"Balances and limits on each card"},"related":[{"slug":"credit-card-payoff","name":"Credit Card Payoff Time and Interest"},{"slug":"dti-ratios","name":"Debt-to-Income Ratios and Affordable Housing Payment"},{"slug":"good-debt-test","name":"Good Debt vs Bad Debt Test"}],"related_ids":["F102","F105","F101"],"group":"Personal finance","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Utilization</mtext><mo>=</mo><mfrac><mrow><mo>\u2211</mo><mtext>Balances</mtext></mrow><mrow><mo>\u2211</mo><mtext>Credit\xa0limits</mtext></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Utilization}=\\\\frac{\\\\sum \\\\text{Balances}}{\\\\sum \\\\text{Credit limits}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"credit-union-member-benefit","name":"Credit Union Member Benefit and Net Worth Ratio"},"next":{"slug":"cva-approximation","name":"Credit Valuation Adjustment (CVA)"},"lesson":null,"total":522}')}}]);